func printTasksTable(tasks []Task, truncated bool) {
	sortTasks(tasks)
	// Header
	fmt.Printf("\x1b[4;38;5;250;48;5;232m%-3s %-9s %-5s %-10s %-8s %-35s \x1b[0m\n", "ID", "Priority", "Tags", "Due", "Project", "Summary")
	for _, t := range tasks {
		var color string
		switch t.Priority {
		case "P0":
			color = "\x1b[0;38;5;160;48;5;232m"
		case "P1":
			color = "\x1b[0;38;5;166;48;5;232m"
		case "P2":
			if t.Status == "active" {
				color = "\x1b[0;38;5;233;48;5;250m"
			} else if t.Status == "paused" {
				color = "\x1b[0;38;5;250;48;5;236m"
			} else {
				color = "\x1b[0;38;5;250;48;5;233m"
			}
		case "P3":
			color = "\x1b[0;38;5;245;48;5;232m"
		default:
			color = "\x1b[0;38;5;250;48;5;233m"
		}
		// Special for active/paused override?
		if t.Status == "active" {
			color = "\x1b[0;38;5;233;48;5;250m"
		} else if t.Status == "paused" {
			color = "\x1b[0;38;5;250;48;5;236m"
		}
		tagsStr := strings.Join(t.Tags, ",")
		dueStr := ""
		if !t.Due.IsZero() && t.Due.Format("2006-01-02") != "0001-01-01" {
			dueStr = t.Due.Format("2 Jan 2006")
		}
		summary := t.Summary
		if truncated && len(summary) > 35 {
			summary = summary[:35]
		}
		fmt.Printf("%s%-3d %-9s %-5s %-10s %-8s %-35s \x1b[0m\n", color, t.ID, t.Priority, tagsStr, dueStr, t.Project, summary)
	}
	fmt.Printf("\n%d tasks.\n", len(tasks))
	// Show active context if exists
	ctx := getContextQuery()
	if !isContextEmpty(ctx) {
		// Reconstruct context string?
		var parts []string
		for _, tag := range ctx.Tags {
			parts = append(parts, "+"+tag)
		}
		for _, tag := range ctx.AntiTags {
			parts = append(parts, "-"+tag)
		}
		if ctx.Project != "" {
			parts = append(parts, "project:"+ctx.Project)
		}
		for _, p := range ctx.AntiProjects {
			parts = append(parts, "-project:"+p)
		}
		if ctx.Priority != "" {
			parts = append(parts, ctx.Priority)
		}
		if !ctx.Due.IsZero() {
			parts = append(parts, "due:"+ctx.Due.Format("2006-01-02"))
		}
		if ctx.Text != "" {
			parts = append(parts, ctx.Text)
		}
		fmt.Printf("\x1b[33mActive context: %s\x1b[0m\n", strings.Join(parts, " "))
	}
}

