// Helpers for git operations for task files

func taskFilePath(t Task) string {
	return filepath.Join(repoPath, t.Status, t.UUID+".yml")
}

func findTaskByID(id int) (*Task, string) {
	tasks := loadAllTasks()
	for _, t := range tasks {
		if t.ID == id {
			// need to find actual file location
			// The task's Status field indicates dir
			copyTask := t
			return &copyTask, taskFilePath(t)
		}
	}
	return nil, ""
}

func findTaskByUUID(uuid string) (*Task, string) {
	for _, status := range statusDirs {
		path := filepath.Join(repoPath, status, uuid+".yml")
		if _, err := os.Stat(path); err == nil {
			content, _ := os.ReadFile(path)
			t := parseTaskYAML(string(content))
			t.UUID = uuid
			t.Status = status
			if status != "resolved" {
				if id, ok := idsMap[uuid]; ok {
					t.ID = id
				}
			} else {
				t.ID = 0
			}
			return &t, path
		}
	}
	return nil, ""
}

func moveTaskFile(oldPath, newStatus string, uuid string) string {
	newPath := filepath.Join(repoPath, newStatus, uuid+".yml")
	os.MkdirAll(filepath.Join(repoPath, newStatus), 0700)
	os.Rename(oldPath, newPath)
	return newPath
}

// Command handlers

func handleAdd(tokens []string, ctx Query) {
	q := parseQueryTokens(tokens, true)
	// check ignore context
	if !q.IgnoreContext && !isContextEmpty(ctx) {
		// apply context tags/project/priority/due to q if not already set?
		// For add, context should add tags/project etc to new task
		for _, tag := range ctx.Tags {
			found := false
			for _, t := range q.Tags {
				if t == tag {
					found = true
					break
				}
			}
			if !found {
				q.Tags = append(q.Tags, tag)
			}
		}
		if q.Project == "" && ctx.Project != "" {
			q.Project = ctx.Project
		}
		if q.Priority == "" && ctx.Priority != "" {
			q.Priority = ctx.Priority
		}
		if q.Due.IsZero() && !ctx.Due.IsZero() {
			q.Due = ctx.Due
		}
		sort.Strings(q.Tags)
	}
	if q.Text == "" && q.Template == 0 {
		fmt.Fprintf(os.Stderr, "\x1b[31mtask description or template required\x1b[0m\n")
		os.Exit(1)
	}
	var base Task
	hasBase := false
	if q.Template != 0 {
		// need to find template task with ID == Template
		all := loadAllTasks()
		var tmpl *Task
		for _, t := range all {
			if t.ID == q.Template && t.Status == "template" {
				copyT := t
				tmpl = &copyT
				break
			}
		}
		if tmpl == nil {
			// also check if ID corresponds to non-template? Original says if template:1 where 1 is pending, it warns "You've copied an open task! To learn more..."
			// Let's search any task with that ID (non-template)
			for _, t := range all {
				if t.ID == q.Template {
					copyT := t
					tmpl = &copyT
					fmt.Printf("You've copied an open task!\nTo learn more about creating templates enter 'dstask help template'\n")
					break
				}
			}
		}
		if tmpl == nil {
			fmt.Fprintf(os.Stderr, "\x1b[31mno open task with ID %d exists\x1b[0m\n", q.Template)
			os.Exit(1)
		}
		base = *tmpl
		hasBase = true
		// For add from template, the new task's summary should be q.Text if provided, else base summary?
		// If q.Text is provided, use it as new summary, else use base summary?
		// In our earlier test, add template:1 "derived" gave summary "derived" not original.
		// So if Text provided, override base summary.
		// If not provided, use base summary?
	}
	summary := q.Text
	if hasBase && summary == "" {
		summary = base.Summary
	}
	// If still empty? maybe error?
	// Create new task
	uuid := generateUUID()
	nextID := getNextID()
	// clean stale ids for this nextID
	cleanStaleIds(nextID)
	idsMap[uuid] = nextID
	saveIds(idsMap)
	var t Task
	if hasBase {
		t = base
		t.UUID = uuid
		t.ID = nextID
		t.Status = "pending"
		t.Created = time.Now().UTC()
		t.Resolved = time.Time{}
		// Override with q's fields if provided
		if summary != "" {
			t.Summary = summary
		}
		// For tags: if q has tags, merge? Or replace? In test, base had work, new added +home gave both work and home. So merge base tags with q tags.
		// But q.Tags already includes context tags etc. So merge.
		if len(q.Tags) > 0 {
			tagSet := make(map[string]bool)
			for _, tag := range t.Tags {
				tagSet[tag] = true
			}
			for _, tag := range q.Tags {
				tagSet[tag] = true
			}
			var merged []string
			for tag := range tagSet {
				merged = append(merged, tag)
			}
			sort.Strings(merged)
			t.Tags = merged
		}
		if q.Project != "" {
			t.Project = q.Project
		}
		if q.Priority != "" {
			t.Priority = q.Priority
		}
		if !q.Due.IsZero() {
			t.Due = q.Due
		}
		if q.Note != "" {
			t.Notes = q.Note
		}
		// Note: base notes may be preserved? For template copy, notes from base maybe kept? In our test, base notes empty, so fine.
	} else {
		t = Task{
			UUID:     uuid,
			Status:   "pending",
			ID:       nextID,
			Summary:  summary,
			Notes:    q.Note,
			Tags:     q.Tags,
			Project:  q.Project,
			Priority: q.Priority,
			Created:  time.Now().UTC(),
			Due:      q.Due,
		}
		if t.Priority == "" {
			t.Priority = "P2"
		}
	}
	// Write file
	yamlStr := writeTaskYAML(t)
	path := filepath.Join(repoPath, "pending", uuid+".yml")
	os.MkdirAll(filepath.Join(repoPath, "pending"), 0700)
	os.WriteFile(path, []byte(yamlStr), 0600)
	fmt.Printf("Added %d: %s\n", nextID, t.Summary)
	gitAddCommit(fmt.Sprintf("Added %d: %s", nextID, t.Summary), filepath.Join("pending", uuid+".yml"))
}

