							filtered = append(filtered, t)
						}
					}
					newTask.Tags = filtered
				}
				if q.Project != "" {
					newTask.Project = q.Project
				} else if len(remaining) > 0 && strings.Contains(strings.Join(remaining, " "), "project:") {
					// if project: empty specified, need to clear?
