func handleNote(ids []int, tokens []string) {
	if len(ids) == 0 {
		fmt.Fprintf(os.Stderr, "\x1b[31mno ID(s) specified\x1b[0m\n")
		os.Exit(1)
	}
	if len(ids) != 1 {
		// For multiple ids, maybe handle batch? But spec says note <id> <text>, likely only single
	}
	id := ids[0]
	t, path := findTaskByID(id)
	if t == nil {
		fmt.Fprintf(os.Stderr, "\x1b[31mno open task with ID %d exists\x1b[0m\n", id)
		os.Exit(1)
	}
	if len(tokens) == 0 {
		// open editor
		editor := os.Getenv("EDITOR")
		if editor == "" {
			editor = os.Getenv("VISUAL")
		}
		if editor == "" {
			fmt.Fprintf(os.Stderr, "\x1b[31mFailed to run $EDITOR\x1b[0m\n")
			os.Exit(1)
		}
		// create temp file with current notes
		tmpfile, err := os.CreateTemp("", "dstask-note-*.md")
		if err != nil {
			fmt.Fprintf(os.Stderr, "\x1b[31mFailed to run $EDITOR\x1b[0m\n")
			os.Exit(1)
		}
		tmpPath := tmpfile.Name()
		tmpfile.WriteString(t.Notes)
		tmpfile.Close()
		cmd := exec.Command("sh", "-c", editor+" \"$1\"", "--", tmpPath)
		cmd.Stdin = os.Stdin
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		if err := cmd.Run(); err != nil {
			fmt.Fprintf(os.Stderr, "\x1b[31mFailed to run $EDITOR\x1b[0m\n")
			os.Remove(tmpPath)
			os.Exit(1)
		}
		newContent, _ := os.ReadFile(tmpPath)
		os.Remove(tmpPath)
		newNotes := string(newContent)
		// Trim trailing newline? Original may keep as is but strip?
		// Compare if changed
		if newNotes == t.Notes {
			fmt.Printf("\x1b[38;5;245mNo changes detected\x1b[0m\n")
			return
		}
		t.Notes = newNotes
		yamlStr := writeTaskYAML(*t)
		os.WriteFile(path, []byte(yamlStr), 0600)
		fmt.Printf("Edited %d: %s\n", id, t.Summary)
		gitAddCommit(fmt.Sprintf("Edited %d: %s", id, t.Summary), filepath.Join(t.Status, t.UUID+".yml"))
		return
	}
	// append text
	noteText := strings.Join(tokens, " ")
	// If t.Notes is empty, set to noteText, else append with newline?
	// Earlier we observed after stop note, notes became block with leading newline and spaces: "  stop note here" preceded by blank line
	// For note append, if existing notes empty, set to noteText
	// If not empty, append "\n" + noteText? Check earlier: after first note "first note", notes was "first note"? After second note "second", notes became? We didn't capture. Let's assume append with "\n"
	if t.Notes == "" {
		t.Notes = noteText
	} else {
		// Append with newline and maybe double? In earlier stop note test, after stop note "stop note here", notes became "\n  stop note here" ?? Actually file showed:
		// notes: |2-
		// 
		//   stop note here
		// That corresponds to notes string "\nstop note here"? Let's see: parse of block gave join with "\n" of lines, but there was blank line then "stop note here". That suggests notes = "\nstop note here"? Or "\n\nstop note here"? Need to deduce.
		// For simplicity, if notes already contains newline block, we will append with "\n" + noteText
		if strings.HasSuffix(t.Notes, "\n") {
			t.Notes = t.Notes + noteText
		} else {
			t.Notes = t.Notes + "\n" + noteText
		}
		// But for first stop note, notes was "" initially, so after stop it set to "\nstop note here"? Let's check: after stop, file had notes: |2- blank line then content, which corresponds to notes string with leading newline? The string we store may be "\nstop note here"? Let's replicate: In write, if notes contains newline, we output block with blank line? Our write outputs block with blank line after |2- then indented lines. That matches observed: after |2- there is blank line, so notes string likely starts with "\n". Let's set initial notes as "\n" + noteText? For append when empty, should set to "\n"+noteText to produce block? But earlier note via "/" with single line gave plain not block. So note append vs stop note may differ.
		// For note command append, maybe notes are appended with "\n" without leading blank? Let's just append with "\n"
	}
	yamlStr := writeTaskYAML(*t)
	os.WriteFile(path, []byte(yamlStr), 0600)
	fmt.Printf("Edited %d: %s\n", id, t.Summary)
	gitAddCommit(fmt.Sprintf("Edited %d: %s", id, t.Summary), filepath.Join(t.Status, t.UUID+".yml"))
}

func handleStop(ids []int, tokens []string) {
	if len(ids) == 0 {
		fmt.Fprintf(os.Stderr, "\x1b[31mno ID(s) specified\x1b[0m\n")
		os.Exit(1)
	}
	all := loadAllTasks()
	for _, id := range ids {
		var found *Task
		var path string
		for _, t := range all {
			if t.ID == id {
				copyT := t
				found = &copyT
				path = taskFilePath(t)
				break
			}
		}
		if found == nil {
			fmt.Fprintf(os.Stderr, "\x1b[31mno open task with ID %d exists\x1b[0m\n", id)
			continue
		}
		if found.Status != "active" {
			fmt.Fprintf(os.Stderr, "\x1b[31minvalid state transition: %s -> paused\x1b[0m\n", found.Status)
			continue
		}
		noteText := strings.Join(tokens, " ")
		if noteText != "" {
			if found.Notes == "" {
				found.Notes = "\n" + noteText
			} else {
				// Append with newline? For stop, notes should be appended with newline + text, but ensure leading newline handling
				if strings.HasSuffix(found.Notes, "\n") {
					found.Notes = found.Notes + noteText
				} else {
					found.Notes = found.Notes + "\n" + noteText
				}
			}
		}
		// Move to paused
		oldPath := path
		// Update file before move? Need to write updated yaml to oldPath then move
		yamlStr := writeTaskYAML(*found)
		os.WriteFile(oldPath, []byte(yamlStr), 0600)
		newPath := moveTaskFile(oldPath, "paused", found.UUID)
		fmt.Printf("Stopped %d: %s\n", id, found.Summary)
		cmd := exec.Command("git", "-C", repoPath, "add", "-A")
		cmd.Run()
		cmd = exec.Command("git", "-C", repoPath, "commit", "-m", fmt.Sprintf("Stopped %d: %s", id, found.Summary))
		out, _ := cmd.CombinedOutput()
		for _, l := range strings.Split(strings.TrimSpace(string(out)), "\n") {
			if strings.TrimSpace(l) != "" {
				fmt.Printf("\x1b[38;5;245m%s\x1b[0m\n", l)
			}
		}
		_ = newPath
		all = loadAllTasks()
	}
}

func handleDone(ids []int, tokens []string) {
	if len(ids) == 0 {
		fmt.Fprintf(os.Stderr, "\x1b[31mno ID(s) specified\x1b[0m\n")
		os.Exit(1)
	}
	all := loadAllTasks()
	for _, id := range ids {
		var found *Task
		var path string
		for _, t := range all {
			if t.ID == id {
				copyT := t
				found = &copyT
				path = taskFilePath(t)
				break
			}
		}
		if found == nil {
			fmt.Fprintf(os.Stderr, "\x1b[31mno open task with ID %d exists\x1b[0m\n", id)
			continue
		}
		if found.Status == "resolved" {
			fmt.Fprintf(os.Stderr, "\x1b[31minvalid state transition: %s -> resolved\x1b[0m\n", found.Status)
			continue
		}
		if found.Status == "template" {
			fmt.Fprintf(os.Stderr, "\x1b[31minvalid state transition: %s -> resolved\x1b[0m\n", found.Status)
			continue
		}
		noteText := strings.Join(tokens, " ")
		if noteText != "" {
			if found.Notes == "" {
				found.Notes = "\n" + noteText
			} else {
				if strings.HasSuffix(found.Notes, "\n") {
					found.Notes = found.Notes + noteText
				} else {
					found.Notes = found.Notes + "\n" + noteText
				}
			}
		}
		found.Status = "resolved"
		found.Resolved = time.Now().UTC()
		yamlStr := writeTaskYAML(*found)
		os.WriteFile(path, []byte(yamlStr), 0600)
		oldPath := path
		newPath := moveTaskFile(oldPath, "resolved", found.UUID)
		// For resolved, the ID should become 0 in output, but we keep mapping? The file still exists but ID not used.
		fmt.Printf("Resolved %d: %s\n", id, found.Summary)
		cmd := exec.Command("git", "-C", repoPath, "add", "-A")
		cmd.Run()
		cmd = exec.Command("git", "-C", repoPath, "commit", "-m", fmt.Sprintf("Resolved %d: %s", id, found.Summary))
		out, _ := cmd.CombinedOutput()
		for _, l := range strings.Split(strings.TrimSpace(string(out)), "\n") {
			if strings.TrimSpace(l) != "" {
				fmt.Printf("\x1b[38;5;245m%s\x1b[0m\n", l)
			}
		}
		_ = newPath
		all = loadAllTasks()
	}
}

func handleContext(tokens []string) {
	if len(tokens) == 0 {
		// maybe show current context?
		ctx := getContextQuery()
		if isContextEmpty(ctx) {
			fmt.Println("No context")
		} else {
			var parts []string
			for _, t := range ctx.Tags {
				parts = append(parts, "+"+t)
			}
			for _, t := range ctx.AntiTags {
				parts = append(parts, "-"+t)
			}
			if ctx.Project != "" {
				parts = append(parts, "project:"+ctx.Project)
			}
			fmt.Println(strings.Join(parts, " "))
		}
		return
	}
	joined := strings.Join(tokens, " ")
	if joined == "none" || joined == "--" {
		state.Context = Query{}
		saveState(state)
		// also need to clear? In earlier test, context none cleared file to contain empty context? We saw state.bin after context none maybe still contains but empty? Our save will store empty.
		return
	}
	q := parseQueryTokens(tokens, false)
	// context cannot contain text
	if q.Text != "" {
		fmt.Fprintf(os.Stderr, "\x1b[31mcontext cannot contain text\x1b[0m\n")
		os.Exit(1)
	}
	// Save to state
	state.Context = q
	// Need to set Cmd field to "context" like earlier decode showed? But not needed for filtering; we can just store Query
	state.Context.Cmd = "context"
	saveState(state)
	// For display, maybe print context?
	// Original context command prints nothing on success (empty stdout)
}

func handleModify(ids []int, tokens []string) {
	q := parseQueryTokens(tokens, false)
	// Modifiable attributes: tags, project, priority (maybe also due? but ignore)
	if len(q.Tags) == 0 && len(q.AntiTags) == 0 && q.Project == "" && len(q.AntiProjects) == 0 && q.Priority == "" && q.Text != "" {
		// Text not allowed for modify? But we can ignore
	}
	all := loadAllTasks()
	var targets []Task
	if len(ids) > 0 {
		for _, id := range ids {
			for _, t := range all {
				if t.ID == id {
					targets = append(targets, t)
					break
				}
			}
		}
		if len(targets) != len(ids) {
			// some missing? Check
			for _, id := range ids {
				found := false
				for _, t := range targets {
					if t.ID == id {
						found = true
						break
					}
				}
				if !found {
					fmt.Fprintf(os.Stderr, "\x1b[31mno open task with ID %d exists\x1b[0m\n", id)
				}
			}
		}
	} else {
		// No ids, modify all tasks in current context subject to confirmation
		ctx := getContextQuery()
		// Filter tasks that are non-resolved, non-template
		var candidates []Task
		for _, t := range all {
			if t.Status == "resolved" || t.Status == "template" {
				continue
			}
			candidates = append(candidates, t)
		}
		filtered := filterTasks(candidates, q, ctx) // Actually q is modify filter, but we need to filter candidates by context? Wait modify without ids should modify all tasks that match current context, not filtered by q? The q is the modification to apply, not filter. So how to determine which tasks to modify?
		// The original behavior: modify without ID will be performed to all tasks in the current context subject to confirmation. So the set is tasks that match context (not q). Q is the modification spec.
		// So we need to filter candidates by context only.
		contextFiltered := filterTasks(candidates, Query{}, ctx) // empty query + ctx => just ctx filter
		// But if context is empty (no filter), then contextFiltered is all candidates.
		// However our earlier test with context +work and modify +newtag without ids modified exactly tasks matching context (2 tasks). That matches.
		// If context is none, modify without ids should modify all tasks? In earlier test with context none and modify +x without ids (non-pty) it modified all 3 tasks. That matches.
		filtered = contextFiltered
		// Now need to apply modifications q to each filtered task
		// But we need confirmation if is tty? Original says hit y to confirm. In non-tty, maybe auto-accept? Our earlier test showed even with input n it still modified. But we need to handle prompt when tty.
		// For simplicity, if isTty or DSTASK_FAKE_PTY, we would prompt? But our earlier test with echo n still modified, suggesting prompt not honored? Maybe original's prompt is to press y, but if stdin is not tty, it still modifies without prompt.
		// We'll implement: if isTty() and not piped, prompt.
		// For now, for non-tty, auto-modify.
		// For tty, prompt user
		if isTty() {
			fmt.Printf("Modify %d tasks? (y/n) ", len(filtered))
			var resp string
			fmt.Scanln(&resp)
			if strings.ToLower(strings.TrimSpace(resp)) != "y" {
				fmt.Println("Aborted")
				return
			}
		}
		targets = filtered
	}
	// Apply modifications
	for _, target := range targets {
		// Find path
		path := taskFilePath(target)
		// Read latest
		content, _ := os.ReadFile(path)
		t := parseTaskYAML(string(content))
		t.UUID = target.UUID
		t.Status = target.Status
		t.ID = target.ID
		t.Created = target.Created
		t.Resolved = target.Resolved
		t.Due = target.Due
		// Apply tags
		originalTags := append([]string{}, t.Tags...)
		originalProject := t.Project
		originalPriority := t.Priority
		// Add tags
		for _, tag := range q.Tags {
			found := false
			for _, have := range t.Tags {
				if have == tag {
					found = true
					break
				}
			}
			if !found {
				t.Tags = append(t.Tags, tag)
			}
		}
		// Remove anti-tags
		for _, anti := range q.AntiTags {
			var newTags []string
			for _, have := range t.Tags {
				if have != anti {
					newTags = append(newTags, have)
				}
			}
			t.Tags = newTags
		}
		// Project
		if q.Project != "" {
			t.Project = q.Project
		}
		// Check for clearing project: if tokens contain "project:" exactly, set to ""
		// Need to detect if original tokens included "project:" with empty value
		// Our parse sets Project to "" when token is "project:", but we lost info whether it was explicitly set to clear vs not set. We can check if any token is "project:" or "project: "?
		// For now, if any modify token is "project:" (empty), we clear.
		for _, tok := range tokens {
			if tok == "project:" {
				t.Project = ""
			}
			if strings.HasPrefix(tok, "-project:") {
				// already handled as AntiProjects? But for modify, -project:website means clear if matches? Actually example: modify -work +home project:workbench -project:website => This would remove tag work, add home, set project to workbench, and if project was website, remove? But -project: handling ambiguous.
				// We'll treat -project: value as removing that project if current equals that value
				val := strings.TrimPrefix(tok, "-project:")
				if t.Project == val {
					t.Project = ""
				}
			}
		}
		for _, ap := range q.AntiProjects {
			if t.Project == ap {
				t.Project = ""
			}
		}
		if q.Priority != "" {
			t.Priority = q.Priority
		}
		// Due? Not listed as modifiable, ignore
		sort.Strings(t.Tags)
		// Check if changed
		changed := false
		if len(originalTags) != len(t.Tags) {
			changed = true
		} else {
			for i, tag := range originalTags {
				if tag != t.Tags[i] {
					changed = true
					break
				}
			}
		}
		if originalProject != t.Project || originalPriority != t.Priority {
			changed = true
		}
		if !changed {
			fmt.Printf("\x1b[38;5;245mNo changes detected\x1b[0m\n")
			continue
		}
		yamlStr := writeTaskYAML(t)
		os.WriteFile(path, []byte(yamlStr), 0600)
		fmt.Printf("Modified %d: %s\n", t.ID, t.Summary)
		cmd := exec.Command("git", "-C", repoPath, "add", "-A")
		cmd.Run()
		cmd = exec.Command("git", "-C", repoPath, "commit", "-m", fmt.Sprintf("Modified %d: %s", t.ID, t.Summary))
		out, _ := cmd.CombinedOutput()
		for _, l := range strings.Split(strings.TrimSpace(string(out)), "\n") {
			if strings.TrimSpace(l) != "" {
				fmt.Printf("\x1b[38;5;245m%s\x1b[0m\n", l)
			}
		}
	}
}

func handleEdit(ids []int) {
	if len(ids) == 0 {
		fmt.Fprintf(os.Stderr, "\x1b[31mno ID(s) specified\x1b[0m\n")
		os.Exit(1)
	}
	editor := os.Getenv("EDITOR")
	if editor == "" {
		editor = os.Getenv("VISUAL")
	}
	if editor == "" {
		fmt.Fprintf(os.Stderr, "\x1b[31mFailed to run $EDITOR\x1b[0m\n")
		os.Exit(1)
	}
	all := loadAllTasks()
	for _, id := range ids {
		var found *Task
		var path string
		for _, t := range all {
			if t.ID == id {
				copyT := t
				found = &copyT
				path = taskFilePath(t)
				break
			}
		}
		if found == nil {
			fmt.Fprintf(os.Stderr, "\x1b[31mno open task with ID %d exists\x1b[0m\n", id)
			continue
		}
		// Create temp file with current yaml
		content, _ := os.ReadFile(path)
		tmpfile, err := os.CreateTemp("", "dstask-edit-*.yml")
		if err != nil {
			fmt.Fprintf(os.Stderr, "\x1b[31mFailed to run $EDITOR\x1b[0m\n")
			continue
		}
		tmpPath := tmpfile.Name()
		tmpfile.Write(content)
		tmpfile.Close()
		cmd := exec.Command("sh", "-c", editor+" \"$1\"", "--", tmpPath)
		cmd.Stdin = os.Stdin
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		if err := cmd.Run(); err != nil {
			fmt.Fprintf(os.Stderr, "\x1b[31mFailed to run $EDITOR\x1b[0m\n")
			os.Remove(tmpPath)
			continue
		}
		newContent, _ := os.ReadFile(tmpPath)
		os.Remove(tmpPath)
		if string(newContent) == string(content) {
			fmt.Printf("\x1b[38;5;245mNo changes detected\x1b[0m\n")
			continue
		}
		// Write back
		os.WriteFile(path, newContent, 0600)
		// Need to update? But we should parse new yaml to get summary for commit message?
		newTask := parseTaskYAML(string(newContent))
		// Keep uuid etc? The yaml may have been edited, but we trust file.
		fmt.Printf("Edited %d: %s\n", id, newTask.Summary)
		cmd2 := exec.Command("git", "-C", repoPath, "add", "-A")
		cmd2.Run()
		cmd2 = exec.Command("git", "-C", repoPath, "commit", "-m", fmt.Sprintf("Edited %d: %s", id, newTask.Summary))
		out, _ := cmd2.CombinedOutput()
		for _, l := range strings.Split(strings.TrimSpace(string(out)), "\n") {
			if strings.TrimSpace(l) != "" {
				fmt.Printf("\x1b[38;5;245m%s\x1b[0m\n", l)
			}
		}
		all = loadAllTasks()
	}
}

func handleUndo(tokens []string) {
	n := 1
	if len(tokens) > 0 {
		fmt.Sscanf(tokens[0], "%d", &n)
		if n < 1 {
			n = 1
		}
	}
	for i := 0; i < n; i++ {
		cmd := exec.Command("git", "-C", repoPath, "revert", "--no-edit", "HEAD")
		out, err := cmd.CombinedOutput()
		outStr := string(out)
		if err != nil {
			// Try reset if revert fails? Original maybe uses reset for undo? Let's check: When we did undo after add, it did revert with message Revert "Added ..."
			// If revert fails due to conflicts, it prints error?
			fmt.Fprintf(os.Stderr, "\x1b[31mFailed to undo\x1b[0m\n")
			fmt.Fprintf(os.Stderr, "%s", outStr)
			break
		}
		// Print the revert commit output? The git revert already creates a commit, its output is like "[master xxx] Revert ..."
		for _, l := range strings.Split(strings.TrimSpace(outStr), "\n") {
			if strings.TrimSpace(l) != "" {
				fmt.Printf("\x1b[38;5;245m%s\x1b[0m\n", l)
			}
		}
	}
}

func handleSync() {
	// git pull then git push
	cmd := exec.Command("git", "-C", repoPath, "pull", "--rebase=false")
	out, err := cmd.CombinedOutput()
	outStr := string(out)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s", outStr)
		fmt.Fprintf(os.Stderr, "\x1b[31mFailed to run git cmd.\x1b[0m\n")
		return
	}
	cmd = exec.Command("git", "-C", repoPath, "push")
	out, err = cmd.CombinedOutput()
	outStr = string(out)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s", outStr)
		fmt.Fprintf(os.Stderr, "\x1b[31mFailed to run git cmd.\x1b[0m\n")
		return
	}
	fmt.Printf("%s", outStr)
}

func handleOpen(ids []int) {
	if len(ids) == 0 {
		fmt.Fprintf(os.Stderr, "\x1b[31mno ID(s) specified\x1b[0m\n")
		os.Exit(1)
	}
	all := loadAllTasks()
	urlRegex := regexp.MustCompile(`https?://[^\s]+`)
	foundURLs := []string{}
	for _, id := range ids {
		var t *Task
		for _, task := range all {
			if task.ID == id {
				copyT := task
				t = &copyT
				break
			}
		}
		if t == nil {
			fmt.Fprintf(os.Stderr, "\x1b[31mno open task with ID %d exists\x1b[0m\n", id)
			continue
		}
		text := t.Summary + " " + t.Notes
		urls := urlRegex.FindAllString(text, -1)
		foundURLs = append(foundURLs, urls...)
	}
	if len(foundURLs) == 0 {
		fmt.Fprintf(os.Stderr, "\x1b[31mFailed to open browser\x1b[0m\n")
		return
	}
	for _, u := range foundURLs {
		var cmd *exec.Cmd
		// try xdg-open, open, etc
		if _, err := exec.LookPath("xdg-open"); err == nil {
			cmd = exec.Command("xdg-open", u)
		} else if _, err := exec.LookPath("open"); err == nil {
			cmd = exec.Command("open", u)
		} else {
			fmt.Fprintf(os.Stderr, "\x1b[31mFailed to open browser\x1b[0m\n")
			return
		}
		if err := cmd.Start(); err != nil {
			fmt.Fprintf(os.Stderr, "\x1b[31mFailed to open browser\x1b[0m\n")
			return
		}
	}
}

func handleGit(args []string) {
	cmd := exec.Command("git", append([]string{"-C", repoPath}, args...)...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		// The original maybe prints error with color? For git failures, it prints Failed to run git cmd.
		// But for git subcommand, it just passes through.
		os.Exit(1)
	}
}

func handleRemove(ids []int) {
	if len(ids) == 0 {
		fmt.Fprintf(os.Stderr, "\x1b[31mno ID(s) specified\x1b[0m\n")
		os.Exit(1)
	}
	all := loadAllTasks()
	for _, id := range ids {
		var found *Task
		var path string
		for _, t := range all {
			if t.ID == id {
				copyT := t
				found = &copyT
				path = taskFilePath(t)
				break
			}
		}
		if found == nil {
			fmt.Fprintf(os.Stderr, "\x1b[31mno open task with ID %d exists\x1b[0m\n", id)
			continue
		}
		fmt.Printf("%d: %s\n", id, found.Summary)
		os.Remove(path)
		fmt.Printf("Removed: %d: %s\n", id, found.Summary)
		cmd := exec.Command("git", "-C", repoPath, "add", "-A")
		cmd.Run()
		cmd = exec.Command("git", "-C", repoPath, "commit", "-m", fmt.Sprintf("Removed: %d: %s", id, found.Summary))
		out, _ := cmd.CombinedOutput()
		for _, l := range strings.Split(strings.TrimSpace(string(out)), "\n") {
			if strings.TrimSpace(l) != "" {
				fmt.Printf("\x1b[38;5;245m%s\x1b[0m\n", l)
			}
		}
		all = loadAllTasks()
	}
}

func handleShowProjects(filterTokens []string) {
	q := parseQueryTokens(filterTokens, false)
	ctx := getContextQuery()
	tasks := loadAllTasks()
	// Filter non-resolved? Actually show-projects should consider all non-resolved? Or all? Let's check earlier: show-projects after adding tasks gave projects with taskCount. It included pending tasks. Does it include resolved? Possibly.
	// We'll consider all tasks except maybe template? But template tasks have project as well? In our earlier test, template with project:test but show-projects after adding template maybe not counted? Let's test: In play16, after creating template with project? We had pending project:proj1 etc, show-projects gave proj1. Template not counted? Need to decide.
	// For now, consider all tasks where Project != "" and status != template? But we should include active/pending/paused/deferred?
	filtered := filterTasks(tasks, q, ctx)
	// Build project map
	type ProjInfo struct {
		Name          string    `json:"name"`
		TaskCount     int       `json:"taskCount"`
		ResolvedCount int       `json:"resolvedCount"`
		Active        bool      `json:"active"`
		Created       time.Time `json:"created"`
		Resolved      time.Time `json:"resolved"`
		Priority      string    `json:"priority"`
	}
	projMap := make(map[string]*ProjInfo)
	for _, t := range filtered {
		if t.Project == "" {
			continue
		}
		// Determine status for project: if any task in project is active? Or we need to consider only tasks in that project?
		// We'll compute task counts per project
		pi, ok := projMap[t.Project]
		if !ok {
			pi = &ProjInfo{Name: t.Project, Created: t.Created, Priority: t.Priority}
			projMap[t.Project] = pi
		}
		pi.TaskCount++
		if t.Status == "resolved" {
			pi.ResolvedCount++
			// Update resolved time maybe latest?
			if t.Resolved.After(pi.Resolved) {
				pi.Resolved = t.Resolved
			}
		}
		if t.Status == "active" {
			pi.Active = true
		}
		if t.Created.Before(pi.Created) {
			pi.Created = t.Created
		}
		// priority for project: maybe highest priority among tasks? Keep first
	}
	var list []*ProjInfo
	for _, v := range projMap {
		list = append(list, v)
	}
	sort.Slice(list, func(i, j int) bool { return list[i].Name < list[j].Name })
	if isTty() {
		// table
		fmt.Printf("\x1b[4;38;5;250;48;5;232m%-10s %-8s %-12s \x1b[0m\n", "Name", "Progress", "Created")
		for _, p := range list {
			// color based on priority? For project table, color maybe high priority?
			var color string
			switch p.Priority {
			case "P0":
				color = "\x1b[0;38;5;160;48;5;232m"
			case "P1":
				color = "\x1b[0;38;5;166;48;5;233m"
			default:
				color = "\x1b[0;38;5;250;48;5;233m"
			}
			progress := fmt.Sprintf("%d/%d", p.ResolvedCount, p.TaskCount)
			createdStr := p.Created.Format("Mon 2 Jan 2006")
			fmt.Printf("%s%-10s %-8s %-12s \x1b[0m\n", color, p.Name, progress, createdStr)
		}
	} else {
		// JSON
		if list == nil {
			list = []*ProjInfo{}
		}
		data, _ := json.MarshalIndent(list, "", "  ")
		fmt.Println(string(data))
	}
}

