	fmt.Println("bash-completion   : Print bash completion script to stdout")
	fmt.Println("fish-completion   : Print fish completion script to stdout")
	fmt.Println("zsh-completion    : Print zsh completion script to stdout")
	fmt.Println("help              : Get help on any command or show this message")
	fmt.Println("version           : Show dstask version information")
	fmt.Println("")
	fmt.Println("Colour Key:")
	fmt.Printf("\x1b[0;38;5;160;48;5;232mCritical priority        \x1b[0m\n")
	fmt.Printf("\x1b[0;38;5;166;48;5;232mHigh priority            \x1b[0m\n")
	fmt.Printf("\x1b[0;38;5;250;48;5;233mNormal priority          \x1b[0m\n")
	fmt.Printf("\x1b[0;38;5;245;48;5;232mLow priority             \x1b[0m\n")
	fmt.Printf("\x1b[0;38;5;233;48;5;250mActive                   \x1b[0m\n")
	fmt.Printf("\x1b[0;38;5;250;48;5;236mPaused                   \x1b[0m\n")
}

func main() {
	repoPath = getRepoPath()
	ensureRepo()
	idsMap = loadIds()
	state = loadState()

	args := os.Args[1:]
	// Handle help with no args? Also version etc
	if len(args) > 0 && args[0] == "help" {
		if len(args) > 1 {
			printHelp(args[1])
		} else {
			printGeneralHelp()
		}
		return
	}
	if len(args) > 0 && args[0] == "version" {
		fmt.Println("Version: Unknown")
		fmt.Println("Git commit: Unknown")
		fmt.Println("Build date: Unknown")
		return
	}
	// Completion scripts
	if len(args) > 0 && args[0] == "bash-completion" {
		fmt.Print("# wire bash completions to dstask completion engine. Some of the workarounds for\n# idiosyncrasies around separation with colons taken from /etc/bash_completion\n\n_dstask() {\n    # reconstruct COMP_WORDS to re-join separations caused by colon (which is a default separator)\n    # yes, this method ends up splitting by spaces, but that's not a problem for the dstask parser\n    # see http://tiswww.case.edu/php/chet/bash/FAQ\n    original_args=( $(echo \"${COMP_WORDS[@]}\" | sed 's/ : /:/g' | sed 's/ :$/:/g') )\n\n    # hand to dstask as canonical args\n    COMPREPLY=( $(dstask _completions \"${original_args[@]}\") )\n\n    # convert dstask's suggestions to remove prefix before colon so complete can understand it\n    local last_arg=\"${original_args[-1]}\"\n    local colon_word=${last_arg%\"${last_arg##*:}\"}\n    local i=${#COMPREPLY[*]}\n    while [[ $((--i)) -ge 0 ]]; do\n        COMPREPLY[$i]=${COMPREPLY[$i]#\"$colon_word\"}\n    done\n}\n\ncomplete -F _dstask dstask\ncomplete -F _dstask task\n#complete -F _dstask n\n#complete -F _dstask t\n")
		return
	}
	if len(args) > 0 && args[0] == "zsh-completion" {
		fmt.Print("#compdef dstask\n#autoload\n\n\n_dstask() {\n    compadd -- $(dstask _completions \"${words[@]}\")\n}\n\ncompdef _dstask dstask\n")
		return
	}
	if len(args) > 0 && args[0] == "fish-completion" {
		fmt.Print("#!/usr/bin/env fish\n\ncomplete -f -c dstask -a (echo (dstask _completions) | string collect)\n#complete -f -c task -a (echo (task _completions) | string collect)\n#complete -f -c t -a (echo (t _completions) | string collect)\n")
		return
	}
	if len(args) > 0 && args[0] == "powershell-completion" {
		fmt.Print("[]")
		return
	}
	if len(args) > 0 && args[0] == "_completions" {
		handleCompletions(args[1:])
		return
	}

	// Parse IDs and command
	// Known commands set includes aliases
	// Find command index
	cmd := ""
	cmdIdx := -1
	for i, tok := range args {
		// ignore numeric? but commands are non-numeric
		if cmdSet[tok] {
			cmd = tok
			cmdIdx = i
			break
		}
		// also handle case where token is like "rm" etc already in set
	}
	// Also check for help as command? Already handled
	var ids []int
	var filterTokens []string

	if cmdIdx == -1 {
		// No command found
		if len(args) == 0 {
			cmd = "next"
		} else {
			// Check if args contain only IDs and maybe -- ?
			allNumeric := true
			tempIds := []int{}
			tempFilters := []string{}
			for _, tok := range args {
				if tok == "--" {
					tempFilters = append(tempFilters, tok)
					continue
				}
				if _, err := fmt.Sscanf(tok, "%d", new(int)); err == nil {
					// Check if tok is purely numeric
					if _, err2 := fmt.Sscanf(tok, "%d", new(int)); err2 == nil {
						// Verify tok is digits only
						isNum := true
						for _, c := range tok {
							if c < '0' || c > '9' {
								isNum = false
								break
							}
						}
						if isNum {
							var id int
							fmt.Sscanf(tok, "%d", &id)
							tempIds = append(tempIds, id)
							continue
						}
					}
				}
				allNumeric = false
				tempFilters = append(tempFilters, tok)
			}
			if allNumeric && len(tempIds) > 0 && len(tempFilters) == 0 {
				// Show task detail for ids
				// Treat as "next" with ids? But we should handle as show detail
				// For each id, show detail
				allTasks := loadAllTasks()
				for _, id := range tempIds {
					var found *Task
					for _, t := range allTasks {
						if t.ID == id {
							copyT := t
							found = &copyT
							break
						}
					}
					if found == nil {
						fmt.Fprintf(os.Stderr, "\x1b[31mno open task with ID %d exists\x1b[0m\n", id)
						continue
					}
					printTaskDetail(*found)
				}
				return
			}
			if allNumeric && len(tempIds) > 0 {
				// Mixed case like "1 --" -> show detail with ignore context
				// If filters contain only "--", treat as detail with ignore
				if len(tempFilters) == 1 && tempFilters[0] == "--" {
					allTasks := loadAllTasks()
					for _, id := range tempIds {
						var found *Task
						for _, t := range allTasks {
							if t.ID == id {
								copyT := t
								found = &copyT
								break
							}
						}
						if found != nil {
							printTaskDetail(*found)
						}
					}
					return
				}
			}
			// Otherwise default to next with filterTokens = args
			cmd = "next"
			filterTokens = args
			ids = []int{}
		}
	} else {
		// Found command, collect ids before and after
		for i, tok := range args {
			if i == cmdIdx {
				continue
			}
			// Check if tok is numeric ID
			isNum := true
			if tok == "--" || tok == "/" {
				continue
			}
			for _, c := range tok {
				if c < '0' || c > '9' {
					isNum = false
					break
				}
			}
			if isNum {
				var id int
				fmt.Sscanf(tok, "%d", &id)
				// Need to decide if this numeric should be considered ID or part of summary text?
				// For commands like add, numeric text could be summary? But IDs are typically only for commands that take IDs.
				// For safety, only treat numeric as ID if command is one that accepts IDs (most except add/log/template/context etc)
				// For add, template, log, context, etc, numeric tokens are part of summary not IDs.
				// Let's define which commands accept IDs
				acceptsIDs := map[string]bool{
					"start": true, "stop": true, "done": true, "resolve": true, "note": true, "notes": true, "edit": true, "remove": true, "rm": true, "open": true, "modify": true,
				}
				if acceptsIDs[cmd] {
					ids = append(ids, id)
				} else {
					filterTokens = append(filterTokens, tok)
				}
			} else {
				filterTokens = append(filterTokens, tok)
			}
		}
		// But we lost order for filterTokens that include non-numeric before and after? The above merges but loses order distinction? For simplicity, reconstruct filterTokens as args excluding cmd and numeric ids that were counted.
		// Actually we need to preserve original order of non-id tokens.
		// Our loop already preserves order for filterTokens (non-numeric). For ids, order is as encountered.
		// However for commands that accept IDs, numeric tokens before and after should both be considered.
		// For commands that don't accept IDs, numeric tokens remain in filterTokens.
		// Also need to handle "--" and "/" tokens: they were skipped above, but they should be part of filterTokens for parsing.
		// Let's re-parse filterTokens correctly including those.
		filterTokens = []string{}
		for i, tok := range args {
			if i == cmdIdx {
				continue
			}
			isNum := true
			for _, c := range tok {
				if c < '0' || c > '9' {
					isNum = false
					break
				}
			}
			if isNum {
				acceptsIDs := map[string]bool{
					"start": true, "stop": true, "done": true, "resolve": true, "note": true, "notes": true, "edit": true, "remove": true, "rm": true, "open": true, "modify": true,
				}
				if acceptsIDs[cmd] {
					// already added to ids, skip adding to filter
					continue
				}
			}
			filterTokens = append(filterTokens, tok)
		}
	}

	// Handle command aliases
	if cmd == "rm" {
		cmd = "remove"
	}
	if cmd == "notes" {
		cmd = "note"
	}
	if cmd == "resolve" {
		cmd = "done"
	}
	if cmd == "show-next" {
		cmd = "next"
	}

	ctx := getContextQuery()

	switch cmd {
	case "next":
		// Filter tasks: show open tasks (pending/active/paused) filtered
		q := parseQueryTokens(filterTokens, false)
		// Note: next should ignore? It should apply context unless -- is present (handled in parse)
		tasks := loadAllTasks()
		var open []Task
		for _, t := range tasks {
			if t.Status == "pending" || t.Status == "active" || t.Status == "paused" {
				open = append(open, t)
			}
		}
		filtered := filterTasks(open, q, ctx)
		if isTty() {
			printTasksTable(filtered, true)
		} else {
			printTasksJSON(filtered)
		}
	case "add":
		handleAdd(filterTokens, ctx)
	case "template":
		handleTemplate(filterTokens)
	case "log":
		handleLog(filterTokens)
	case "start":
		handleStart(ids, filterTokens)
	case "note":
		handleNote(ids, filterTokens)
	case "stop":
		handleStop(ids, filterTokens)
	case "done":
		handleDone(ids, filterTokens)
	case "context":
		handleContext(filterTokens)
	case "modify":
		handleModify(ids, filterTokens)
	case "edit":
		handleEdit(ids)
	case "undo":
		handleUndo(filterTokens)
	case "sync":
		handleSync()
	case "open":
		handleOpen(ids)
	case "git":
		handleGit(filterTokens)
	case "remove":
		handleRemove(ids)
	case "show-projects":
		handleShowProjects(filterTokens)
	case "show-tags":
		handleShowTags(filterTokens)
	case "show-active":
		handleShowActive(filterTokens)
	case "show-paused":
		handleShowPaused(filterTokens)
	case "show-open":
		handleShowOpen(filterTokens)
	case "show-resolved":
		handleShowResolved(filterTokens)
	case "show-templates":
		handleShowTemplates(filterTokens)
	case "show-unorganised":
		handleShowUnorganised(filterTokens)
	case "help":
		if len(filterTokens) > 0 {
			printHelp(filterTokens[0])
		} else {
			printGeneralHelp()
		}
	case "version":
		fmt.Println("Version: Unknown")
		fmt.Println("Git commit: Unknown")
		fmt.Println("Build date: Unknown")
	default:
		// Unknown command? Show help?
		// Check if cmd is actually a filter text for next? Could be treat as next with text?
		// If we reached here, cmd is next but with unknown? Already handled.
		// For unknown command with no ids, maybe treat as next? Let's just print help?
		if cmd != "" && !cmdSet[cmd] {
			fmt.Printf("[]")
		} else {
			printGeneralHelp()
		}
	}
}
GO
"}

