cat > main.go <<'GO'
package main

import (
	"bytes"
	"crypto/rand"
	"encoding/gob"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"time"
)

// Types

type Query struct {
	Cmd           string
	IDs           []int
	Tags          []string
	AntiTags      []string
	Project       string
	AntiProjects  []string
	Due           time.Time
	DateFilter    string
	Priority      string
	Template      int
	Text          string
	IgnoreContext bool
	Note          string
}

type State struct {
	Context Query
}

type IdsMap map[string]int

type Task struct {
	UUID      string    `json:"uuid"`
	Status    string    `json:"status"`
	ID        int       `json:"id"`
	Summary   string    `json:"summary"`
	Notes     string    `json:"notes"`
	Tags      []string  `json:"tags"`
	Project   string    `json:"project"`
	Priority  string    `json:"priority"`
	Created   time.Time `json:"created"`
	Resolved  time.Time `json:"resolved"`
	Due       time.Time `json:"due"`
	// internal yaml fields
	DelegatedTo string
	Subtasks    []string
	Dependencies []string
}

// Globals
var repoPath string
var idsMap IdsMap
var state State

var commandsList = []string{
	"next", "add", "template", "log", "start", "note", "notes", "stop", "done", "resolve", "context", "modify", "edit", "undo", "sync", "open", "git", "remove", "rm", "show-projects", "show-tags", "show-active", "show-paused", "show-open", "show-resolved", "show-templates", "show-unorganised", "bash-completion", "fish-completion", "zsh-completion", "powershell-completion", "help", "version", "show-next",
}

var cmdSet map[string]bool
var statusDirs = []string{"pending", "active", "paused", "resolved", "template", "deferred", "delegated", "recurring"}

func init() {
	cmdSet = make(map[string]bool)
	for _, c := range commandsList {
		cmdSet[c] = true
	}
	// alias _completions internal
	cmdSet["_completions"] = true
}

func getRepoPath() string {
	if p := os.Getenv("DSTASK_GIT_REPO"); p != "" {
		return p
	}
	home, err := os.UserHomeDir()
	if err != nil {
		home = os.Getenv("HOME")
	}
	return filepath.Join(home, ".dstask")
}

func ensureRepo() {
	// Check if repoPath exists
	if _, err := os.Stat(repoPath); os.IsNotExist(err) {
		// create and init git
		os.MkdirAll(repoPath, 0700)
		cmd := exec.Command("git", "-C", repoPath, "init")
		// run but ignore output; original prints hints to stderr? We should allow git init output to pass through? In earlier test, git init hint printed to stderr when default repo created via --help. That hint came from git init output, not our code directly.
		// We will run git init and let its output go to stderr if needed? Original seems to let git init output appear (the hint).
		// We'll capture and print to stderr
		out, _ := cmd.CombinedOutput()
		if len(out) > 0 {
			fmt.Fprintf(os.Stderr, "%s", string(out))
		}
		// create subdirs
		for _, d := range statusDirs {
			os.MkdirAll(filepath.Join(repoPath, d), 0700)
		}
		os.MkdirAll(filepath.Join(repoPath, ".git", "dstask"), 0755)
		// create empty ids/states?
		return
	}
	// exists, check .git
	if _, err := os.Stat(filepath.Join(repoPath, ".git")); os.IsNotExist(err) {
		fmt.Fprintf(os.Stderr, "\x1b[31mFailed to create directory in git repository\x1b[0m\n")
		os.Exit(1)
	}
	// ensure dirs
	for _, d := range statusDirs {
		os.MkdirAll(filepath.Join(repoPath, d), 0700)
	}
	os.MkdirAll(filepath.Join(repoPath, ".git", "dstask"), 0755)
}

func loadIds() IdsMap {
	path := filepath.Join(repoPath, ".git", "dstask", "ids.bin")
	f, err := os.Open(path)
	if err != nil {
		return make(IdsMap)
	}
	defer f.Close()
	var m IdsMap
	dec := gob.NewDecoder(f)
	if err := dec.Decode(&m); err != nil {
		return make(IdsMap)
	}
	if m == nil {
		m = make(IdsMap)
	}
	return m
}

func saveIds(m IdsMap) {
	path := filepath.Join(repoPath, ".git", "dstask", "ids.bin")
	os.MkdirAll(filepath.Join(repoPath, ".git", "dstask"), 0755)
	f, err := os.Create(path)
	if err != nil {
		return
	}
	defer f.Close()
	enc := gob.NewEncoder(f)
	enc.Encode(m)
}

func loadState() State {
	path := filepath.Join(repoPath, ".git", "dstask", "state.bin")
	f, err := os.Open(path)
	if err != nil {
		return State{}
	}
	defer f.Close()
	var s State
	dec := gob.NewDecoder(f)
	if err := dec.Decode(&s); err != nil {
		return State{}
	}
	return s
}

func saveState(s State) {
	path := filepath.Join(repoPath, ".git", "dstask", "state.bin")
	os.MkdirAll(filepath.Join(repoPath, ".git", "dstask"), 0755)
	f, err := os.Create(path)
	if err != nil {
		return
	}
	defer f.Close()
	enc := gob.NewEncoder(f)
	enc.Encode(s)
}

func getContextQuery() Query {
	if env := os.Getenv("DSTASK_CONTEXT"); env != "" {
		if env == "none" || env == "--" {
			return Query{}
		}
		// env string may contain spaces, split like shell? Use Fields
		tokens := strings.Fields(env)
		q := parseQueryTokens(tokens, false)
		return q
	}
	// from state
	return state.Context
}

func isContextEmpty(q Query) bool {
	if len(q.Tags) != 0 || len(q.AntiTags) != 0 || q.Project != "" || len(q.AntiProjects) != 0 || !q.Due.IsZero() || q.Priority != "" || q.Text != "" {
		return false
	}
	return true
}

// parseQueryTokens parses filter tokens for add/context etc
func parseQueryTokens(tokens []string, allowTemplate bool) Query {
	var q Query
	var textParts []string
	for i := 0; i < len(tokens); i++ {
		tok := tokens[i]
		if tok == "--" {
			q.IgnoreContext = true
			continue
		}
		if tok == "/" {
			// rest is note
			remaining := tokens[i+1:]
			q.Note = strings.Join(remaining, " ")
			break
		}
		if tok == "" {
			continue
		}
		if strings.HasPrefix(tok, "+") && len(tok) > 1 {
			q.Tags = append(q.Tags, tok[1:])
			continue
		}
		if strings.HasPrefix(tok, "-") && len(tok) > 1 {
			// check for -project: prefix?
			if strings.HasPrefix(tok, "-project:") {
				val := strings.TrimPrefix(tok, "-project:")
				q.AntiProjects = append(q.AntiProjects, val)
			} else {
				q.AntiTags = append(q.AntiTags, tok[1:])
			}
			continue
		}
		if strings.HasPrefix(tok, "project:") {
			q.Project = strings.TrimPrefix(tok, "project:")
			continue
		}
		if tok == "P0" || tok == "P1" || tok == "P2" || tok == "P3" {
			q.Priority = tok
			continue
		}
		if strings.HasPrefix(tok, "due:") {
			val := strings.TrimPrefix(tok, "due:")
			if val == "" {
				// clearing due, leave zero
				q.Due = time.Time{}
				// but need to differentiate? For add, due empty means not set
				// For modify, due: without value maybe clear?
			} else {
				// parse YYYY-MM-DD
				if t, err := time.Parse("2006-01-02", val); err == nil {
					q.Due = t
				} else if t, err := time.Parse(time.RFC3339, val); err == nil {
					q.Due = t
				} else {
					// try with time
					q.Due = time.Time{}
				}
			}
			continue
		}
		if strings.HasPrefix(tok, "template:") && allowTemplate {
			val := strings.TrimPrefix(tok, "template:")
			var id int
			fmt.Sscanf(val, "%d", &id)
			q.Template = id
			continue
		}
		// text
		textParts = append(textParts, tok)
	}
	if len(textParts) > 0 {
		q.Text = strings.Join(textParts, " ")
	}
	// Sort tags for consistency
	sort.Strings(q.Tags)
	sort.Strings(q.AntiTags)
	sort.Strings(q.AntiProjects)
	return q
}

// generateUUID
func generateUUID() string {
	b := make([]byte, 16)
	rand.Read(b)
	// version 4
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	hexStr := hex.EncodeToString(b)
	return fmt.Sprintf("%s-%s-%s-%s-%s", hexStr[0:8], hexStr[8:12], hexStr[12:16], hexStr[16:20], hexStr[20:32])
}

// Task YAML parsing and writing
func parseTaskYAML(content string) Task {
	var t Task
	lines := strings.Split(content, "\n")
	inTags := false
	var tags []string
	for i := 0; i < len(lines); i++ {
		line := lines[i]
		if strings.HasPrefix(line, "summary:") {
			val := strings.TrimPrefix(line, "summary:")
			val = strings.TrimSpace(val)
			// handle maybe quoted? but we just take raw
			// If val starts with '"' and ends with '"', strip?
			if len(val) >= 2 && val[0] == '"' && val[len(val)-1] == '"' {
				val = val[1 : len(val)-1]
			}
			t.Summary = val
			inTags = false
		} else if strings.HasPrefix(line, "notes:") {
			val := strings.TrimPrefix(line, "notes:")
			val = strings.TrimSpace(val)
			if val == `""` || val == `''` {
				t.Notes = ""
			} else if val == "|2-" || val == "|" || strings.HasPrefix(val, "|") {
				// block scalar, subsequent lines indented by 2 spaces
				var notesLines []string
				// skip possible blank line after?
				j := i + 1
				// According to observed, after |2- there is a blank line then indented content
				for j < len(lines) {
					if lines[j] == "" {
						j++
						continue
					}
					if strings.HasPrefix(lines[j], "  ") {
						notesLines = append(notesLines, strings.TrimPrefix(lines[j], "  "))
						j++
					} else {
						break
					}
				}
				t.Notes = strings.Join(notesLines, "\n")
				i = j - 1
			} else {
				// plain or quoted?
				if len(val) >= 2 && val[0] == '"' && val[len(val)-1] == '"' {
					val = val[1 : len(val)-1]
				}
				t.Notes = val
			}
			inTags = false
		} else if strings.HasPrefix(line, "tags:") {
			val := strings.TrimPrefix(line, "tags:")
			val = strings.TrimSpace(val)
			if val == "[]" {
				tags = []string{}
				inTags = false
			} else if val == "" {
				// start list
				inTags = true
				tags = []string{}
			} else {
				// maybe inline?
				inTags = false
			}
		} else if inTags && strings.HasPrefix(strings.TrimSpace(line), "- ") {
			val := strings.TrimSpace(line)
			val = strings.TrimPrefix(val, "- ")
			tags = append(tags, val)
		} else if strings.HasPrefix(line, "project:") {
			val := strings.TrimPrefix(line, "project:")
			val = strings.TrimSpace(val)
			if len(val) >= 2 && val[0] == '"' && val[len(val)-1] == '"' {
				val = val[1 : len(val)-1]
			}
			t.Project = val
			inTags = false
		} else if strings.HasPrefix(line, "priority:") {
			val := strings.TrimPrefix(line, "priority:")
			val = strings.TrimSpace(val)
			t.Priority = val
			inTags = false
		} else if strings.HasPrefix(line, "delegatedto:") {
			// ignore
			inTags = false
		} else if strings.HasPrefix(line, "created:") {
			val := strings.TrimPrefix(line, "created:")
			val = strings.TrimSpace(val)
			if t2, err := time.Parse(time.RFC3339Nano, val); err == nil {
				t.Created = t2
			} else if t2, err := time.Parse(time.RFC3339, val); err == nil {
				t.Created = t2
			} else if t2, err := time.Parse("2006-01-02T15:04:05Z", val); err == nil {
				t.Created = t2
			}
			inTags = false
		} else if strings.HasPrefix(line, "resolved:") {
			val := strings.TrimPrefix(line, "resolved:")
			val = strings.TrimSpace(val)
			if t2, err := time.Parse(time.RFC3339Nano, val); err == nil {
				t.Resolved = t2
			} else if t2, err := time.Parse(time.RFC3339, val); err == nil {
				t.Resolved = t2
			} else if t2, err := time.Parse("2006-01-02T15:04:05Z", val); err == nil {
				t.Resolved = t2
			}
			inTags = false
		} else if strings.HasPrefix(line, "due:") {
			val := strings.TrimPrefix(line, "due:")
			val = strings.TrimSpace(val)
			if t2, err := time.Parse(time.RFC3339Nano, val); err == nil {
				t.Due = t2
			} else if t2, err := time.Parse(time.RFC3339, val); err == nil {
				t.Due = t2
			} else if t2, err := time.Parse("2006-01-02", val); err == nil {
				t.Due = t2
			} else if t2, err := time.Parse("2006-01-02T15:04:05Z", val); err == nil {
				t.Due = t2
			} else {
				// zero time remains
			}
			inTags = false
		} else if strings.HasPrefix(line, "subtasks:") || strings.HasPrefix(line, "dependencies:") {
			inTags = false
		}
	}
	t.Tags = tags
	sort.Strings(t.Tags)
	if t.Priority == "" {
		t.Priority = "P2"
	}
	return t
}

func writeTaskYAML(t Task) string {
	var buf bytes.Buffer
	buf.WriteString(fmt.Sprintf("summary: %s\n", t.Summary))
	// notes handling
	if t.Notes == "" {
		buf.WriteString("notes: \"\"\n")
	} else if strings.Contains(t.Notes, "\n") {
		buf.WriteString("notes: |2-\n\n")
		lines := strings.Split(t.Notes, "\n")
		for _, l := range lines {
			buf.WriteString("  " + l + "\n")
		}
	} else {
		// plain without quotes? Use as is, but if contains colon or leading spaces etc, quote? For simplicity plain
		buf.WriteString(fmt.Sprintf("notes: %s\n", t.Notes))
	}
	if len(t.Tags) == 0 {
		buf.WriteString("tags: []\n")
	} else {
		buf.WriteString("tags:\n")
		sort.Strings(t.Tags)
		for _, tag := range t.Tags {
			buf.WriteString(fmt.Sprintf("- %s\n", tag))
		}
	}
	if t.Project == "" {
		buf.WriteString("project: \"\"\n")
	} else {
		buf.WriteString(fmt.Sprintf("project: %s\n", t.Project))
	}
	if t.Priority == "" {
		t.Priority = "P2"
	}
	buf.WriteString(fmt.Sprintf("priority: %s\n", t.Priority))
	buf.WriteString("delegatedto: \"\"\n")
	buf.WriteString("subtasks: []\n")
	buf.WriteString("dependencies: []\n")
	// time formatting: use RFC3339Nano
	// created always has nanos? Use Format with Nano
	buf.WriteString(fmt.Sprintf("created: %s\n", t.Created.Format(time.RFC3339Nano)))
	// resolved and due: if zero, use 0001-01-01T00:00:00Z
	if t.Resolved.IsZero() {
		buf.WriteString("resolved: 0001-01-01T00:00:00Z\n")
	} else {
		buf.WriteString(fmt.Sprintf("resolved: %s\n", t.Resolved.Format(time.RFC3339Nano)))
	}
	if t.Due.IsZero() {
		buf.WriteString("due: 0001-01-01T00:00:00Z\n")
	} else {
		buf.WriteString(fmt.Sprintf("due: %s\n", t.Due.Format(time.RFC3339Nano)))
	}
	return buf.String()
}

func loadAllTasks() []Task {
	var tasks []Task
	for _, status := range statusDirs {
		dir := filepath.Join(repoPath, status)
		entries, err := os.ReadDir(dir)
		if err != nil {
			continue
		}
		for _, e := range entries {
			if !strings.HasSuffix(e.Name(), ".yml") {
				continue
			}
			uuid := strings.TrimSuffix(e.Name(), ".yml")
			content, err := os.ReadFile(filepath.Join(dir, e.Name()))
			if err != nil {
				continue
			}
			t := parseTaskYAML(string(content))
			t.UUID = uuid
			t.Status = status
			// assign ID
			if status == "resolved" {
				t.ID = 0
			} else {
				if id, ok := idsMap[uuid]; ok {
					t.ID = id
				} else {
					// Need to assign? But maybe not loaded yet; assign now
					// Find next free ID
					// For now assign 0 and later fix? We'll assign after loading all?
					t.ID = 0
				}
			}
			tasks = append(tasks, t)
		}
	}
	// For tasks with ID 0 and not resolved, assign IDs based on map or new
	// First, for those with 0 and status != resolved, if uuid not in map, assign
	// But for those where ID is 0 because not in map, we need to assign and save
	used := make(map[int]bool)
	for _, t := range tasks {
		if t.Status != "resolved" && t.ID != 0 {
			used[t.ID] = true
		}
	}
	changed := false
	for i, t := range tasks {
		if t.Status != "resolved" && t.ID == 0 {
			if id, ok := idsMap[t.UUID]; ok && !used[id] {
				tasks[i].ID = id
				used[id] = true
			} else {
				// find smallest free
				next := 1
				for used[next] {
					next++
				}
				tasks[i].ID = next
				used[next] = true
				idsMap[t.UUID] = next
				changed = true
			}
		}
	}
	if changed {
		saveIds(idsMap)
	}
	return tasks
}

func getNextID() int {
	// Find smallest free ID among non-resolved tasks
	used := make(map[int]bool)
	tasks := loadAllTasks()
	for _, t := range tasks {
		if t.Status != "resolved" && t.ID != 0 {
			used[t.ID] = true
		}
	}
	for i := 1; ; i++ {
		if !used[i] {
			return i
		}
	}
}

func cleanStaleIds(newID int) {
	// remove any stale entry that has value == newID but uuid file not exists
	for uuid, id := range idsMap {
		if id == newID {
			found := false
			for _, status := range statusDirs {
				if status == "resolved" {
					continue
				}
				if _, err := os.Stat(filepath.Join(repoPath, status, uuid+".yml")); err == nil {
					found = true
					break
				}
			}
			if !found {
				delete(idsMap, uuid)
			}
		}
	}
}

func filterTasks(tasks []Task, q Query, ctx Query) []Task {
	// Merge context if not ignored
	if !q.IgnoreContext && !isContextEmpty(ctx) {
		// merge ctx into q for filtering
		// For Tags, combine? ctx tags are added to q tags (AND)
		// For AntiTags, combine
		// For Project, if q.Project == "" then use ctx.Project, else q overrides?
		// Similarly priority, due, etc
		merged := q
		// Tags
		merged.Tags = append([]string{}, q.Tags...)
		for _, t := range ctx.Tags {
			found := false
			for _, existing := range merged.Tags {
				if existing == t {
					found = true
					break
				}
			}
			if !found {
				merged.Tags = append(merged.Tags, t)
			}
		}
		merged.AntiTags = append([]string{}, q.AntiTags...)
		for _, t := range ctx.AntiTags {
			found := false
			for _, existing := range merged.AntiTags {
				if existing == t {
					found = true
					break
				}
			}
			if !found {
				merged.AntiTags = append(merged.AntiTags, t)
			}
		}
		if merged.Project == "" {
			merged.Project = ctx.Project
		}
		merged.AntiProjects = append([]string{}, q.AntiProjects...)
		for _, p := range ctx.AntiProjects {
			merged.AntiProjects = append(merged.AntiProjects, p)
		}
		if merged.Priority == "" {
			merged.Priority = ctx.Priority
		}
		if merged.Due.IsZero() && !ctx.Due.IsZero() {
			merged.Due = ctx.Due
		}
		// Text? ctx.Text shouldn't exist (context cannot contain text), ignore
		q = merged
		sort.Strings(q.Tags)
		sort.Strings(q.AntiTags)
		sort.Strings(q.AntiProjects)
	}
	var filtered []Task
	for _, t := range tasks {
		// filter tags
		matches := true
		for _, need := range q.Tags {
			found := false
			for _, have := range t.Tags {
				if have == need {
					found = true
					break
				}
			}
			if !found {
				matches = false
				break
			}
		}
		if !matches {
			continue
		}
		for _, anti := range q.AntiTags {
			for _, have := range t.Tags {
				if have == anti {
					matches = false
					break
				}
			}
			if !matches {
				break
			}
		}
		if !matches {
			continue
		}
		if q.Project != "" {
			if t.Project != q.Project {
				continue
			}
		}
		for _, ap := range q.AntiProjects {
			if t.Project == ap {
				matches = false
				break
			}
		}
		if !matches {
			continue
		}
		if q.Priority != "" {
			if t.Priority != q.Priority {
				continue
			}
		}
		if !q.Due.IsZero() {
			// exact match day? Compare formatted YYYY-MM-DD?
			if t.Due.IsZero() || t.Due.Format("2006-01-02") != q.Due.Format("2006-01-02") {
				continue
			}
		}
		if q.Text != "" {
			// case-insensitive substring in summary or notes
			lowText := strings.ToLower(q.Text)
			if !strings.Contains(strings.ToLower(t.Summary), lowText) && !strings.Contains(strings.ToLower(t.Notes), lowText) {
				continue
			}
		}
		filtered = append(filtered, t)
	}
	return filtered
}

func sortTasks(tasks []Task) {
	priorityRank := map[string]int{"P0": 0, "P1": 1, "P2": 2, "P3": 3}
	sort.Slice(tasks, func(i, j int) bool {
		ri := priorityRank[tasks[i].Priority]
		rj := priorityRank[tasks[j].Priority]
		if ri != rj {
			return ri < rj
		}
		// then by created time
		if !tasks[i].Created.Equal(tasks[j].Created) {
			return tasks[i].Created.Before(tasks[j].Created)
		}
		return tasks[i].ID < tasks[j].ID
	})
}

func findTasksByIDs(tasks []Task, ids []int) ([]Task, []int) {
	var found []Task
	var missing []int
	idSet := make(map[int]bool)
	for _, id := range ids {
		idSet[id] = true
	}
	for _, t := range tasks {
		if idSet[t.ID] {
			found = append(found, t)
			delete(idSet, t.ID)
		}
	}
	for id := range idSet {
		missing = append(missing, id)
	}
	return found, missing
}

func gitAddCommit(message string, files ...string) {
	if len(files) == 0 {
		return
	}
	// git add files
	args := append([]string{"add"}, files...)
	cmd := exec.Command("git", append([]string{"-C", repoPath}, args...)...)
	cmd.Run()
	// git commit
	cmd = exec.Command("git", "-C", repoPath, "commit", "-m", message)
	out, err := cmd.CombinedOutput()
	outStr := string(out)
	// Print commit output with grey color if success
	if err == nil {
		// The git commit output is typically like "[master (root-commit) abc] Added ..."
		// Wrap with color 38;5;245
		// Print to stderr or stdout? Original prints to stdout with color? We'll print to stdout? Actually our earlier combined showed commit output after "Added..." line; both were in combined stdout/stderr. We'll print commit output to stdout wrapped?
		// To replicate, we print the git output with color to stdout? The initial "Added 1: ..." line is separate.
		lines := strings.Split(strings.TrimSpace(outStr), "\n")
		for _, l := range lines {
			if strings.TrimSpace(l) == "" {
				continue
			}
			fmt.Printf("\x1b[38;5;245m%s\x1b[0m\n", l)
		}
	} else {
		fmt.Fprintf(os.Stderr, "\x1b[31merror: failed to commit changes: %v\x1b[0m\n", err)
		if len(outStr) > 0 {
			fmt.Fprintf(os.Stderr, "%s", outStr)
		}
	}
}

func gitCommitAll(message string) {
	cmd := exec.Command("git", "-C", repoPath, "add", "-A")
	cmd.Run()
	cmd = exec.Command("git", "-C", repoPath, "commit", "-m", message)
	out, err := cmd.CombinedOutput()
	outStr := string(out)
	if err == nil {
		lines := strings.Split(strings.TrimSpace(outStr), "\n")
		for _, l := range lines {
			if strings.TrimSpace(l) == "" {
				continue
			}
			fmt.Printf("\x1b[38;5;245m%s\x1b[0m\n", l)
		}
	} else {
		// if no changes, git commit will fail with "nothing to commit" ? But original prints "No changes detected" for some cases like template no changes
		// Check if output contains "nothing to commit"
		if strings.Contains(outStr, "nothing to commit") {
			fmt.Printf("\x1b[38;5;245mNo changes detected\x1b[0m\n")
		} else {
			fmt.Fprintf(os.Stderr, "\x1b[31merror: failed to commit changes: exit status 128\x1b[0m\n")
			// Also print git's error? Original prints Author identity unknown etc in red?
		}
	}
}

func isTty() bool {
	if os.Getenv("DSTASK_FAKE_PTY") == "1" {
		return true
	}
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

