// Helpers for git operations for task files

func taskFilePath(t Task) string {
	return filepath.Join(repoPath, t.Status, t.UUID+".yml")
}

func findTaskByID(id int) (*Task, string) {
	tasks := loadAllTasks()
	for _, t := range tasks {
		if t.ID == id {
			// need to find actual file location
			// The task's Status field indicates dir
			copyTask := t
			return &copyTask, taskFilePath(t)
		}
	}
	return nil, ""
}

func findTaskByUUID(uuid string) (*Task, string) {
	for _, status := range statusDirs {
		path := filepath.Join(repoPath, status, uuid+".yml")
		if _, err := os.Stat(path); err == nil {
			content, _ := os.ReadFile(path)
			t := parseTaskYAML(string(content))
			t.UUID = uuid
			t.Status = status
			if status != "resolved" {
				if id, ok := idsMap[uuid]; ok {
					t.ID = id
				}
			} else {
				t.ID = 0
			}
			return &t, path
		}
	}
	return nil, ""
}

func moveTaskFile(oldPath, newStatus string, uuid string) string {
	newPath := filepath.Join(repoPath, newStatus, uuid+".yml")
	os.MkdirAll(filepath.Join(repoPath, newStatus), 0700)
	os.Rename(oldPath, newPath)
	return newPath
}

// Command handlers

func handleAdd(tokens []string, ctx Query) {
	q := parseQueryTokens(tokens, true)
	// check ignore context
	if !q.IgnoreContext && !isContextEmpty(ctx) {
		// apply context tags/project/priority/due to q if not already set?
		// For add, context should add tags/project etc to new task
		for _, tag := range ctx.Tags {
			found := false
			for _, t := range q.Tags {
				if t == tag {
					found = true
					break
				}
			}
			if !found {
				q.Tags = append(q.Tags, tag)
			}
		}
		if q.Project == "" && ctx.Project != "" {
			q.Project = ctx.Project
		}
		if q.Priority == "" && ctx.Priority != "" {
			q.Priority = ctx.Priority
		}
		if q.Due.IsZero() && !ctx.Due.IsZero() {
			q.Due = ctx.Due
		}
		sort.Strings(q.Tags)
	}
	if q.Text == "" && q.Template == 0 {
		fmt.Fprintf(os.Stderr, "\x1b[31mtask description or template required\x1b[0m\n")
		os.Exit(1)
	}
	var base Task
	hasBase := false
	if q.Template != 0 {
		// need to find template task with ID == Template
		all := loadAllTasks()
		var tmpl *Task
