				saveIds(idsMap)
				newTask := *found
				newTask.UUID = newUUID
				newTask.ID = nextID
				newTask.Status = "template"
				newTask.Created = time.Now().UTC()
				newTask.Resolved = time.Time{}
				if q.Text != "" {
					newTask.Summary = q.Text
				}
				if len(q.Tags) > 0 {
					// merge?
					tagSet := make(map[string]bool)
					for _, t := range newTask.Tags {
						tagSet[t] = true
					}
					for _, t := range q.Tags {
						tagSet[t] = true
					}
					var merged []string
					for t := range tagSet {
						merged = append(merged, t)
					}
					sort.Strings(merged)
					newTask.Tags = merged
				}
				// handle anti-tags?
				for _, anti := range q.AntiTags {
					var filtered []string
					for _, t := range newTask.Tags {
						if t != anti {
							filtered = append(filtered, t)
						}
					}
					newTask.Tags = filtered
				}
				if q.Project != "" {
					newTask.Project = q.Project
				} else if len(remaining) > 0 && strings.Contains(strings.Join(remaining, " "), "project:") {
					// if project: empty specified, need to clear?
					// Check if any token is "project:" exactly?
					for _, tok := range remaining {
						if tok == "project:" {
							newTask.Project = ""
						}
					}
