	}
	// Otherwise, tokens are for new template creation (no ID)
	q := parseQueryTokens(tokens, true)
	if !q.IgnoreContext {
		ctx := getContextQuery()
		if !isContextEmpty(ctx) {
			for _, tag := range ctx.Tags {
				found := false
