				}
				if !found {
					q.Tags = append(q.Tags, tag)
				}
			}
			if q.Project == "" && ctx.Project != "" {
				q.Project = ctx.Project
			}
			if q.Priority == "" && ctx.Priority != "" {
				q.Priority = ctx.Priority
			}
			if q.Due.IsZero() && !ctx.Due.IsZero() {
				q.Due = ctx.Due
			}
			sort.Strings(q.Tags)
		}
	}
	if q.Text == "" {
		fmt.Fprintf(os.Stderr, "\x1b[31mtask description or template required\x1b[0m\n")
		os.Exit(1)
	}
	// create template task
	uuid := generateUUID()
	nextID := getNextID()
	cleanStaleIds(nextID)
	idsMap[uuid] = nextID
	saveIds(idsMap)
	t := Task{
		UUID:     uuid,
		Status:   "template",
		ID:       nextID,
		Summary:  q.Text,
		Notes:    q.Note,
		Tags:     q.Tags,
		Project:  q.Project,
