func handleStop(ids []int, tokens []string) {
	if len(ids) == 0 {
		fmt.Fprintf(os.Stderr, "\x1b[31mno ID(s) specified\x1b[0m\n")
		os.Exit(1)
	}
	all := loadAllTasks()
	for _, id := range ids {
		var found *Task
		var path string
		for _, t := range all {
			if t.ID == id {
				copyT := t
				found = &copyT
				path = taskFilePath(t)
				break
			}
		}
		if found == nil {
			fmt.Fprintf(os.Stderr, "\x1b[31mno open task with ID %d exists\x1b[0m\n", id)
			continue
		}
		if found.Status != "active" {
			fmt.Fprintf(os.Stderr, "\x1b[31minvalid state transition: %s -> paused\x1b[0m\n", found.Status)
			continue
		}
		noteText := strings.Join(tokens, " ")
		if noteText != "" {
			if found.Notes == "" {
				found.Notes = "\n" + noteText
			} else {
				// Append with newline? For stop, notes should be appended with newline + text, but ensure leading newline handling
				if strings.HasSuffix(found.Notes, "\n") {
					found.Notes = found.Notes + noteText
				} else {
					found.Notes = found.Notes + "\n" + noteText
				}
			}
		}
		// Move to paused
		oldPath := path
		// Update file before move? Need to write updated yaml to oldPath then move
		yamlStr := writeTaskYAML(*found)
		os.WriteFile(oldPath, []byte(yamlStr), 0600)
		newPath := moveTaskFile(oldPath, "paused", found.UUID)
		fmt.Printf("Stopped %d: %s\n", id, found.Summary)
		cmd := exec.Command("git", "-C", repoPath, "add", "-A")
		cmd.Run()
		cmd = exec.Command("git", "-C", repoPath, "commit", "-m", fmt.Sprintf("Stopped %d: %s", id, found.Summary))
		out, _ := cmd.CombinedOutput()
		for _, l := range strings.Split(strings.TrimSpace(string(out)), "\n") {
			if strings.TrimSpace(l) != "" {
				fmt.Printf("\x1b[38;5;245m%s\x1b[0m\n", l)
			}
		}
		_ = newPath
		all = loadAllTasks()
	}
}

