func handleModify(ids []int, tokens []string) {
	q := parseQueryTokens(tokens, false)
	// Modifiable attributes: tags, project, priority (maybe also due? but ignore)
	if len(q.Tags) == 0 && len(q.AntiTags) == 0 && q.Project == "" && len(q.AntiProjects) == 0 && q.Priority == "" && q.Text != "" {
		// Text not allowed for modify? But we can ignore
	}
	all := loadAllTasks()
	var targets []Task
	if len(ids) > 0 {
		for _, id := range ids {
			for _, t := range all {
				if t.ID == id {
					targets = append(targets, t)
					break
				}
			}
		}
		if len(targets) != len(ids) {
			// some missing? Check
			for _, id := range ids {
				found := false
				for _, t := range targets {
					if t.ID == id {
						found = true
						break
					}
				}
				if !found {
					fmt.Fprintf(os.Stderr, "\x1b[31mno open task with ID %d exists\x1b[0m\n", id)
				}
			}
		}
	} else {
		// No ids, modify all tasks in current context subject to confirmation
		ctx := getContextQuery()
		// Filter tasks that are non-resolved, non-template
		var candidates []Task
		for _, t := range all {
			if t.Status == "resolved" || t.Status == "template" {
				continue
			}
			candidates = append(candidates, t)
		}
		filtered := filterTasks(candidates, q, ctx) // Actually q is modify filter, but we need to filter candidates by context? Wait modify without ids should modify all tasks that match current context, not filtered by q? The q is the modification to apply, not filter. So how to determine which tasks to modify?
		// The original behavior: modify without ID will be performed to all tasks in the current context subject to confirmation. So the set is tasks that match context (not q). Q is the modification spec.
		// So we need to filter candidates by context only.
		contextFiltered := filterTasks(candidates, Query{}, ctx) // empty query + ctx => just ctx filter
		// But if context is empty (no filter), then contextFiltered is all candidates.
		// However our earlier test with context +work and modify +newtag without ids modified exactly tasks matching context (2 tasks). That matches.
		// If context is none, modify without ids should modify all tasks? In earlier test with context none and modify +x without ids (non-pty) it modified all 3 tasks. That matches.
		filtered = contextFiltered
		// Now need to apply modifications q to each filtered task
		// But we need confirmation if is tty? Original says hit y to confirm. In non-tty, maybe auto-accept? Our earlier test showed even with input n it still modified. But we need to handle prompt when tty.
		// For simplicity, if isTty or DSTASK_FAKE_PTY, we would prompt? But our earlier test with echo n still modified, suggesting prompt not honored? Maybe original's prompt is to press y, but if stdin is not tty, it still modifies without prompt.
		// We'll implement: if isTty() and not piped, prompt.
		// For now, for non-tty, auto-modify.
		// For tty, prompt user
		if isTty() {
			fmt.Printf("Modify %d tasks? (y/n) ", len(filtered))
			var resp string
			fmt.Scanln(&resp)
			if strings.ToLower(strings.TrimSpace(resp)) != "y" {
				fmt.Println("Aborted")
				return
			}
		}
		targets = filtered
	}
	// Apply modifications
	for _, target := range targets {
		// Find path
		path := taskFilePath(target)
		// Read latest
		content, _ := os.ReadFile(path)
		t := parseTaskYAML(string(content))
		t.UUID = target.UUID
		t.Status = target.Status
		t.ID = target.ID
		t.Created = target.Created
		t.Resolved = target.Resolved
		t.Due = target.Due
		// Apply tags
		originalTags := append([]string{}, t.Tags...)
		originalProject := t.Project
		originalPriority := t.Priority
		// Add tags
		for _, tag := range q.Tags {
			found := false
			for _, have := range t.Tags {
				if have == tag {
					found = true
					break
				}
			}
			if !found {
				t.Tags = append(t.Tags, tag)
			}
		}
		// Remove anti-tags
		for _, anti := range q.AntiTags {
			var newTags []string
			for _, have := range t.Tags {
				if have != anti {
					newTags = append(newTags, have)
				}
			}
			t.Tags = newTags
		}
		// Project
		if q.Project != "" {
			t.Project = q.Project
		}
		// Check for clearing project: if tokens contain "project:" exactly, set to ""
		// Need to detect if original tokens included "project:" with empty value
		// Our parse sets Project to "" when token is "project:", but we lost info whether it was explicitly set to clear vs not set. We can check if any token is "project:" or "project: "?
		// For now, if any modify token is "project:" (empty), we clear.
		for _, tok := range tokens {
			if tok == "project:" {
				t.Project = ""
			}
			if strings.HasPrefix(tok, "-project:") {
				// already handled as AntiProjects? But for modify, -project:website means clear if matches? Actually example: modify -work +home project:workbench -project:website => This would remove tag work, add home, set project to workbench, and if project was website, remove? But -project: handling ambiguous.
				// We'll treat -project: value as removing that project if current equals that value
				val := strings.TrimPrefix(tok, "-project:")
				if t.Project == val {
					t.Project = ""
				}
			}
		}
		for _, ap := range q.AntiProjects {
			if t.Project == ap {
				t.Project = ""
			}
		}
		if q.Priority != "" {
			t.Priority = q.Priority
		}
		// Due? Not listed as modifiable, ignore
		sort.Strings(t.Tags)
		// Check if changed
		changed := false
		if len(originalTags) != len(t.Tags) {
			changed = true
		} else {
			for i, tag := range originalTags {
				if tag != t.Tags[i] {
					changed = true
					break
				}
			}
		}
		if originalProject != t.Project || originalPriority != t.Priority {
			changed = true
		}
		if !changed {
			fmt.Printf("\x1b[38;5;245mNo changes detected\x1b[0m\n")
			continue
		}
		yamlStr := writeTaskYAML(t)
		os.WriteFile(path, []byte(yamlStr), 0600)
		fmt.Printf("Modified %d: %s\n", t.ID, t.Summary)
		cmd := exec.Command("git", "-C", repoPath, "add", "-A")
		cmd.Run()
		cmd = exec.Command("git", "-C", repoPath, "commit", "-m", fmt.Sprintf("Modified %d: %s", t.ID, t.Summary))
		out, _ := cmd.CombinedOutput()
		for _, l := range strings.Split(strings.TrimSpace(string(out)), "\n") {
			if strings.TrimSpace(l) != "" {
				fmt.Printf("\x1b[38;5;245m%s\x1b[0m\n", l)
			}
		}
	}
}

func handleEdit(ids []int) {
	if len(ids) == 0 {
		fmt.Fprintf(os.Stderr, "\x1b[31mno ID(s) specified\x1b[0m\n")
		os.Exit(1)
	}
	editor := os.Getenv("EDITOR")
	if editor == "" {
		editor = os.Getenv("VISUAL")
	}
	if editor == "" {
		fmt.Fprintf(os.Stderr, "\x1b[31mFailed to run $EDITOR\x1b[0m\n")
		os.Exit(1)
	}
	all := loadAllTasks()
	for _, id := range ids {
		var found *Task
		var path string
		for _, t := range all {
			if t.ID == id {
				copyT := t
				found = &copyT
				path = taskFilePath(t)
				break
			}
		}
		if found == nil {
			fmt.Fprintf(os.Stderr, "\x1b[31mno open task with ID %d exists\x1b[0m\n", id)
			continue
		}
		// Create temp file with current yaml
		content, _ := os.ReadFile(path)
		tmpfile, err := os.CreateTemp("", "dstask-edit-*.yml")
		if err != nil {
			fmt.Fprintf(os.Stderr, "\x1b[31mFailed to run $EDITOR\x1b[0m\n")
			continue
		}
		tmpPath := tmpfile.Name()
		tmpfile.Write(content)
		tmpfile.Close()
		cmd := exec.Command("sh", "-c", editor+" \"$1\"", "--", tmpPath)
		cmd.Stdin = os.Stdin
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		if err := cmd.Run(); err != nil {
			fmt.Fprintf(os.Stderr, "\x1b[31mFailed to run $EDITOR\x1b[0m\n")
			os.Remove(tmpPath)
			continue
		}
		newContent, _ := os.ReadFile(tmpPath)
		os.Remove(tmpPath)
		if string(newContent) == string(content) {
			fmt.Printf("\x1b[38;5;245mNo changes detected\x1b[0m\n")
			continue
		}
		// Write back
		os.WriteFile(path, newContent, 0600)
		// Need to update? But we should parse new yaml to get summary for commit message?
		newTask := parseTaskYAML(string(newContent))
		// Keep uuid etc? The yaml may have been edited, but we trust file.
		fmt.Printf("Edited %d: %s\n", id, newTask.Summary)
		cmd2 := exec.Command("git", "-C", repoPath, "add", "-A")
		cmd2.Run()
		cmd2 = exec.Command("git", "-C", repoPath, "commit", "-m", fmt.Sprintf("Edited %d: %s", id, newTask.Summary))
		out, _ := cmd2.CombinedOutput()
		for _, l := range strings.Split(strings.TrimSpace(string(out)), "\n") {
			if strings.TrimSpace(l) != "" {
				fmt.Printf("\x1b[38;5;245m%s\x1b[0m\n", l)
			}
		}
		all = loadAllTasks()
	}
}

func handleUndo(tokens []string) {
	n := 1
	if len(tokens) > 0 {
		fmt.Sscanf(tokens[0], "%d", &n)
		if n < 1 {
			n = 1
		}
	}
	for i := 0; i < n; i++ {
		cmd := exec.Command("git", "-C", repoPath, "revert", "--no-edit", "HEAD")
		out, err := cmd.CombinedOutput()
		outStr := string(out)
		if err != nil {
			// Try reset if revert fails? Original maybe uses reset for undo? Let's check: When we did undo after add, it did revert with message Revert "Added ..."
			// If revert fails due to conflicts, it prints error?
			fmt.Fprintf(os.Stderr, "\x1b[31mFailed to undo\x1b[0m\n")
			fmt.Fprintf(os.Stderr, "%s", outStr)
			break
		}
		// Print the revert commit output? The git revert already creates a commit, its output is like "[master xxx] Revert ..."
		for _, l := range strings.Split(strings.TrimSpace(outStr), "\n") {
			if strings.TrimSpace(l) != "" {
				fmt.Printf("\x1b[38;5;245m%s\x1b[0m\n", l)
			}
		}
	}
}

