func handleOpen(ids []int) {
	if len(ids) == 0 {
		fmt.Fprintf(os.Stderr, "\x1b[31mno ID(s) specified\x1b[0m\n")
		os.Exit(1)
	}
	all := loadAllTasks()
	urlRegex := regexp.MustCompile(`https?://[^\s]+`)
	foundURLs := []string{}
	for _, id := range ids {
		var t *Task
		for _, task := range all {
			if task.ID == id {
				copyT := task
				t = &copyT
				break
			}
		}
		if t == nil {
			fmt.Fprintf(os.Stderr, "\x1b[31mno open task with ID %d exists\x1b[0m\n", id)
			continue
		}
		text := t.Summary + " " + t.Notes
		urls := urlRegex.FindAllString(text, -1)
		foundURLs = append(foundURLs, urls...)
	}
	if len(foundURLs) == 0 {
		fmt.Fprintf(os.Stderr, "\x1b[31mFailed to open browser\x1b[0m\n")
		return
	}
	for _, u := range foundURLs {
		var cmd *exec.Cmd
		// try xdg-open, open, etc
		if _, err := exec.LookPath("xdg-open"); err == nil {
			cmd = exec.Command("xdg-open", u)
		} else if _, err := exec.LookPath("open"); err == nil {
			cmd = exec.Command("open", u)
		} else {
			fmt.Fprintf(os.Stderr, "\x1b[31mFailed to open browser\x1b[0m\n")
			return
		}
		if err := cmd.Start(); err != nil {
			fmt.Fprintf(os.Stderr, "\x1b[31mFailed to open browser\x1b[0m\n")
			return
		}
	}
}

