			if t.Resolved.After(pi.Resolved) {
				pi.Resolved = t.Resolved
			}
		}
		if t.Status == "active" {
			pi.Active = true
		}
		if t.Created.Before(pi.Created) {
			pi.Created = t.Created
		}
		// priority for project: maybe highest priority among tasks? Keep first
	}
	var list []*ProjInfo
	for _, v := range projMap {
		list = append(list, v)
	}
	sort.Slice(list, func(i, j int) bool { return list[i].Name < list[j].Name })
	if isTty() {
		// table
		fmt.Printf("\x1b[4;38;5;250;48;5;232m%-10s %-8s %-12s \x1b[0m\n", "Name", "Progress", "Created")
		for _, p := range list {
			// color based on priority? For project table, color maybe high priority?
			var color string
			switch p.Priority {
			case "P0":
				color = "\x1b[0;38;5;160;48;5;232m"
			case "P1":
				color = "\x1b[0;38;5;166;48;5;233m"
			default:
				color = "\x1b[0;38;5;250;48;5;233m"
			}
			progress := fmt.Sprintf("%d/%d", p.ResolvedCount, p.TaskCount)
			createdStr := p.Created.Format("Mon 2 Jan 2006")
			fmt.Printf("%s%-10s %-8s %-12s \x1b[0m\n", color, p.Name, progress, createdStr)
		}
	} else {
		// JSON
		if list == nil {
			list = []*ProjInfo{}
		}
		data, _ := json.MarshalIndent(list, "", "  ")
		fmt.Println(string(data))
	}
}

func handleShowTags(filterTokens []string) {
	q := parseQueryTokens(filterTokens, false)
	ctx := getContextQuery()
	tasks := loadAllTasks()
	filtered := filterTasks(tasks, q, ctx)
	tagSet := make(map[string]bool)
	for _, t := range filtered {
		if t.Status == "resolved" || t.Status == "template" {
			continue
		}
		for _, tag := range t.Tags {
			tagSet[tag] = true
		}
	}
	var tags []string
	for tag := range tagSet {
		tags = append(tags, tag)
	}
	sort.Strings(tags)
	if isTty() {
		for _, tag := range tags {
			fmt.Println(tag)
		}
	} else {
		for _, tag := range tags {
			fmt.Println(tag)
		}
	}
}

